(()=>{"use strict";const K=e=>{const k=String(e.key||"").toUpperCase();if(k==="F12"||((e.ctrlKey&&e.shiftKey)||(e.metaKey&&e.altKey))&&["I","J","C"].includes(k)||(e.ctrlKey&&k==="U")){e.preventDefault();e.stopPropagation();return false}};document.addEventListener("contextmenu",e=>{e.preventDefault()},{capture:true});document.addEventListener("keydown",K,{capture:true});document.addEventListener("dragstart",e=>{if(e.target&&e.target.tagName==="IMG")e.preventDefault()},{capture:true});document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll("img").forEach(e=>{e.draggable=false;e.setAttribute("draggable","false")})},{once:true});})();